def thump(a=0.14, f=150.0): return O2.thump(a, dur=0.08, f=f, click=0.3)
def meter(n):
    """右上の「直せる箱：8個まで」。区間の頭から 1 個ずつ埋まる。8 を超えるとあふれて赤"""
    def f(t, a, b):
        im = Image.new('RGBA', (W_, H_), (0, 0, 0, 0)); al = min(1.0, (t - a) / 0.3, (b - t) / 0.3)
        if al <= 0: return im
        d = ImageDraw.Draw(im); k = min(n, int((t - a - 0.4) / 0.18) + 1) if t - a > 0.4 else 0; over = k > 8
        d.rounded_rectangle((780, 24, 1256, 178), 18, fill=(250, 250, 248, int(238 * al)))
        d.text((1018, 56), '直せる箱：8個まで', font=F(34), fill=(40, 46, 52, int(255 * al)), anchor='mm')
        for j in range(8):
            x = 806 + j * 54; col = (217, 71, 90) if over else ((138, 144, 151) if j < k else (225, 229, 233))
            d.rounded_rectangle((x, 92, x + 44, 136), 8, fill=(*col, int(255 * al)))
        if k: d.text((1018, 152), '壊れた箱 %d個%s' % (k, '　あふれた' if over else ''), font=F(28), fill=((217, 71, 90) if over else (90, 96, 104)) + (int(255 * al),), anchor='mm')
        return im
    return f
def FAo(f, chime=True):
    """fig_anim の重ね絵（1920）を、確認用（1280）でも本番（1920）でも使えるように"""
    def g(t, a, b):
        im = f(t - a, b - a)
        return im if A.W_ == 1920 else im.resize((A.W_, A.H_), Image.LANCZOS)
    g.chime = chime; return g
import fig_anim as FA
def FAw(fn, chime=True, **cues):
    """声に合わせて動く重ね絵：cues の値は s()/e()/w() のきっかけ。絵には「出てからの秒」で渡す"""
    st = {}
    def g(t, a, b):
        im = fn(t - a, b - a, {k: v - a for k, v in st.get('abs', {}).items()})
        return im if A.W_ == 1920 else im.resize((A.W_, A.H_), Image.LANCZOS)
    g.bind = lambda cue: st.update(abs={k: cue(v) for k, v in cues.items()}); g.chime = chime; return g
